// Common themes extraction
function extractKeyThemes(results) {
  const themes = {
    'too difficult': 0,
    'unclear instructions': 0,
    'technical issues': 0,
    'too frequent': 0,
    'accessibility': 0,
    'prefer alternative': 0
  };

  // Keyword matching
  const keywords = {
    'too difficult': ['hard', 'difficult', 'impossible', 'confusing'],
    'unclear instructions': ['unclear', 'confusing', 'dont understand', 'what do i do'],
    'technical issues': ['not loading', 'broken', 'error', 'bug', 'wont work'],
    'too frequent': ['again', 'every time', 'too often', 'annoying'],
    'accessibility': ['blind', 'screen reader', 'cant see', 'keyboard'],
    'prefer alternative': ['email', 'sms', 'code', 'easier way']
  };

  // Count occurrences
  results.forEach(result => {
    const text = result.text.toLowerCase();
    for (const [theme, words] of Object.entries(keywords)) {
      if (words.some(word => text.includes(word))) {
        themes[theme]++;
      }
    }
  });

  return themes;
}
