```javascript
const teamCapacity = {
  week: {
    p0_slots: 2,            // Can handle 2 P0 items per week
    p1_slots: 3,            // Can handle 3 P1 items per week
    p2_slots: 5,            // Can handle 5 P2 items per week
    p3_slots: 2,            // Can handle 2 P3 items per week
    buffer: 1               // 1 slot for emergencies
  },
  month: {
    p0_slots: 4,
    p1_slots: 8,
    p2_slots: 15,
    p3_slots: 6
  }
};

function allocateResources(actions) {
  const allocation = {
    p0: [],
    p1: [],
    p2: [],
    p3: [],
    deferred: []
  };

  // Fill P0 first
  const p0Actions = actions.filter(a => a.priority === 'P0');
  allocation.p0 = p0Actions.slice(0, teamCapacity.week.p0_slots);

  // Then P1
  const p1Actions = actions.filter(a => a.priority === 'P1');
  allocation.p1 = p1Actions.slice(0, teamCapacity.week.p1_slots);

  // Continue for other priorities...

  return allocation;
}
```

### 2. Dependency Management

```javascript
function handleDependencies(actions) {
  const dependencyGraph = buildDependencyGraph(actions);
  const executionOrder = [];

  // Topological sort to determine order
  while (dependencyGraph.nodes.length > 0) {
    // Find nodes with no dependencies
    const ready = dependencyGraph.nodes.filter(
      node => node.dependencies.length === 0
    );

    if (ready.length === 0) {
      // Circular dependency - need manual resolution
      throw new Error('Circular dependency detected');
    }

    // Add to execution order
    executionOrder.push(...ready);

    // Remove processed nodes and update dependencies
    dependencyGraph.nodes = dependencyGraph.nodes.filter(
      node => !ready.includes(node)
    );

    dependencyGraph.nodes.forEach(node => {
      node.dependencies = node.dependencies.filter(
        dep => !ready.includes(dep)
      );
    });
  }

  return executionOrder;
}
```

