function processDirectRequest(stakeholder, request) {
  const rules = directInfluenceRules[stakeholder.role];

  if (!rules) {
    return { approved: false, reason: 'No direct influence authority' };
  }

  if (!rules.validReasons.includes(request.reason)) {
    return { approved: false, reason: 'Invalid reason for direct elevation' };
  }

  if (rules.requiresJustification && !request.justification) {
    return { approved: false, reason: 'Justification required' };
  }

  // Apply the elevation
  const result = {
    approved: true,
    newPriority: rules.canElevateTo,
    elevatedBy: stakeholder.name,
    timestamp: Date.now(),
    requiresReview: rules.reviewRequired
  };

  // Log for audit
  logPriorityElevation(result);

  return result;
}
