## Stakeholder Input Integration

### 1. Weighted Scoring with Stakeholder Input

We incorporate stakeholder input into our scoring model:

```javascript
function calculatePriorityWithStakeholders(action, stakeholderInputs) {
  let baseScore = calculatePriorityScore(action);

  // Apply stakeholder weights
  let stakeholderAdjustment = 0;

  for (const [stakeholder, input] of Object.entries(stakeholderInputs)) {
    const weight = stakeholders[getStakeholderGroup(stakeholder)].weight;
    const inputScore = normalizeStakeholderInput(input);

    stakeholderAdjustment += (inputScore * weight * 100);
  }

  // Combine base score with stakeholder input
  const combinedScore = (baseScore * 0.7) + (stakeholderAdjustment * 0.3);

  return {
    baseScore,
    stakeholderAdjustment,
    combinedScore,
    breakdown: generateScoreBreakdown(action, stakeholderInputs)
  };
}

function normalizeStakeholderInput(input) {
  // Normalize different input types to 0-1 scale
  if (input.priority) {
    // P0=1.0, P1=0.8, P2=0.6, P3=0.4, P4=0.2
    const priorityMap = { P0: 1.0, P1: 0.8, P2: 0.6, P3: 0.4, P4: 0.2 };
    return priorityMap[input.priority] || 0.5;
  }

  if (input.rating) {
    return input.rating / 10; // Assuming 1-10 scale
  }

  if (input.justification) {
    // Analyze justification text for sentiment and urgency
    return analyzeJustification(input.justification);
  }

  return 0.5; // Default neutral
}
```

### 2. Stakeholder Voting System

For significant decisions, we use a structured voting process:

```javascript
const votingSystem = {
  eligibleVoters: [
    'CISO',
    'Product VP',
    'Engineering Director',
    'Support Director',
    'Legal Counsel',
    'UX Research Lead'
  ],

  voteOptions: {
    critical: { points: 5, label: 'Critical - Do immediately' },
    high: { points: 4, label: 'High - Do this quarter' },
    medium: { points: 3, label: 'Medium - Do when possible' },
    low: { points: 2, label: 'Low - Nice to have' },
    defer: { points: 1, label: 'Defer - Not now' }
  },

  vetoPower: ['CISO', 'Legal Counsel'], // Can veto for security/legal reasons

  quorum: 0.6, // 60% of voters must participate

  calculateResult: function(votes) {
    const totalPoints = votes.reduce((sum, v) => sum + this.voteOptions[v.choice].points, 0);
    const maxPoints = votes.length * 5;
    const averageScore = totalPoints / maxPoints;

    // Check for vetoes
    const vetoes = votes.filter(v => 
      this.vetoPower.includes(v.voter) && v.choice === 'defer'
    );

    return {
      averageScore,
      recommendation: this.getRecommendation(averageScore),
      vetoed: vetoes.length > 0,
      consensus: this.calculateConsensus(votes),
      participation: votes.length / this.eligibleVoters.length
    };
  }
};
```

### 3. Conflict Resolution Framework

When stakeholders disagree:

```javascript
function resolveStakeholderConflict(action, conflictingInputs) {
  const conflicts = identifyConflicts(conflictingInputs);
  const resolutions = [];

  for (const conflict of conflicts) {
    let resolution;

    // Resolution strategy based on conflict type
    switch (conflict.type) {
      case 'priority_disagreement':
        resolution = resolvePriorityConflict(conflict);
        break;

      case 'resource_allocation':
        resolution = resolveResourceConflict(conflict);
        break;

      case 'security_vs_ux':
        resolution = resolveSecurityUxTradeoff(conflict);
        break;

      case 'timeline_disagreement':
        resolution = resolveTimelineConflict(conflict);
        break;

      default:
        resolution = escalateToDecisionMaker(conflict);
    }

    resolutions.push(resolution);
  }

  return resolutions;
}

function resolveSecurityUxTradeoff(conflict) {
  // Security always wins in direct conflicts, but we seek compromise
  const securityInput = conflict.parties.find(p => p.role === 'security');
  const uxInput = conflict.parties.find(p => p.role === 'ux');

  if (securityInput.riskLevel >= 8) {
    // High security risk - security wins
    return {
      resolution: 'security_priority',
      decision: securityInput.recommendation,
      mitigation: 'Implement UX improvements in phase 2',
      communicatedTo: ['ux', 'product', 'engineering']
    };
  } else {
    // Moderate risk - seek compromise
    return {
      resolution: 'compromise',
      decision: findMiddleGround(securityInput, uxInput),
      approach: 'Implement with additional safeguards',
      reviewDate: '3 months post-implementation'
    };
  }
}
