## Stakeholder Empowerment

### 1. Direct Priority Requests

Certain stakeholders can directly influence priorities:

```javascript
const directInfluenceRules = {
  ciso: {
    canElevateTo: 'P0',
    requiresJustification: true,
    reviewRequired: true,
    validReasons: ['security_vulnerability', 'compliance', 'threat_intelligence']
  },

  legal: {
    canElevateTo: 'P0',
    requiresJustification: true,
    reviewRequired: true,
    validReasons: ['compliance', 'legal_risk', 'regulatory_change']
  },

  product_vp: {
    canElevateTo: 'P1',
    requiresJustification: true,
    reviewRequired: false,
    validReasons: ['strategic_initiative', 'customer_commitment', 'revenue_impact']
  },

  support_director: {
    canElevateTo: 'P1',
    requiresJustification: true,
    reviewRequired: true,
    validReasons: ['high_ticket_volume', 'customer_complaints', 'sla_risk']
  }
};

function processDirectRequest(stakeholder, request) {
  const rules = directInfluenceRules[stakeholder.role];

  if (!rules) {
    return { approved: false, reason: 'No direct influence authority' };
  }

  if (!rules.validReasons.includes(request.reason)) {
    return { approved: false, reason: 'Invalid reason for direct elevation' };
  }

  if (rules.requiresJustification && !request.justification) {
    return { approved: false, reason: 'Justification required' };
  }

  // Apply the elevation
  const result = {
    approved: true,
    newPriority: rules.canElevateTo,
    elevatedBy: stakeholder.name,
    timestamp: Date.now(),
    requiresReview: rules.reviewRequired
  };

  // Log for audit
  logPriorityElevation(result);

  return result;
}
```

