  assessment.businessImpact.score = (
    assessment.businessImpact.revenue * 0.4 +
    assessment.businessImpact.cost * 0.3 +
    assessment.businessImpact.brand * 0.3
  );

  // ... similar calculations for other categories

  // Overall recommendation
  assessment.recommendation = generateRecommendation(assessment);
  assessment.priority = calculatePriority(assessment);

  return assessment;
}
```

### 2. Pattern Recognition

We identify patterns across feedback to inform systemic improvements:

```javascript
const patternAnalysis = {
  timeframes: {
    weekly: { window: 7, threshold: 3 },
    monthly: { window: 30, threshold: 5 },
    quarterly: { window: 90, threshold: 10 }
  },

  patternTypes: {
    recurringConcern: {
      description: 'Same concern raised multiple times',
      detection: 'same_category + same_subcategory + similar_description',
      action: 'create_systemic_improvement_initiative'
    },

    stakeholderCluster: {
      description: 'Multiple stakeholders raising similar concerns',
      detection: 'different_stakeholders + same_topic',
      action: 'schedule_stakeholder_alignment_session'
    },

    trendEmergence: {
      description: 'New concern type increasing in frequency',
      detection: 'new_category + increasing_frequency',
      action: 'investigate_and_create_task_force'
    },

    crossProjectIssue: {
      description: 'Same issue across multiple projects',
      detection: 'same_concern + multiple_projects',
      action: 'create_cross_functional_initiative'
    }
  },

  analyzePatterns: function(feedbackItems) {
    const patterns = [];

    // Check for recurring concerns
    const groupedByCategory = groupBy(feedbackItems, 'category');
    for (const [category, items] of Object.entries(groupedByCategory)) {
      if (items.length >= this.timeframes.monthly.threshold) {
        patterns.push({
          type: 'recurringConcern',
          category,
          count: items.length,
          severity: calculateAverageSeverity(items),
          recommendation: 'Create systemic improvement initiative'
        });
      }
    }

    // Check for stakeholder clusters
    const stakeholderConcerns = groupBy(feedbackItems, 'stakeholderId');
    for (const [stakeholderId, items] of Object.entries(stakeholderConcerns)) {
      if (items.length >= 3) {
        patterns.push({
          type: 'stakeholderCluster',
          stakeholder: getStakeholderName(stakeholderId),
          concernCount: items.length,
          topConcerns: getTopConcerns(items),
          recommendation: 'Schedule one-on-one with stakeholder'
        });
      }
    }

    return patterns;
  }
};
```

