      risk_score += 20 if event.get("validation_result") == "rejected"
      risk_score += 15 if event.get("dynamic_elements").size > 3
      risk_score += 10 if event.get("ip_address") =~ /^192\.168\./
      event.set("risk_score", risk_score)
    '
  }
}

output {
  elasticsearch {
    hosts => ["elasticsearch:9200"]
    index => "sql-audit-%{+YYYY.MM.dd}"
  }

  # High-risk events to separate index
