### Machine Learning Anomaly Detection
```python
from sklearn.ensemble import IsolationForest
import numpy as np

class AnomalyDetector:
    def __init__(self):
        self.model = IsolationForest(contamination=0.1, random_state=42)
        self.is_trained = False

    def extract_features(self, log_entries):
        """Extract numerical features from log entries"""
        features = []
        for entry in log_entries:
            feature_vector = [
                len(entry.get('raw_input', '')),
                len(entry.get('dynamic_elements', [])),
                1 if entry.get('validation_result') == 'rejected' else 0,
                entry.get('risk_score', 0),
                len(entry.get('table_name', '')),
                1 if ';' in entry.get('raw_input', '') else 0,
                1 if 'UNION' in entry.get('raw_input', '').upper() else 0,
                1 if 'DROP' in entry.get('raw_input', '').upper() else 0
            ]
            features.append(feature_vector)
        return np.array(features)

    def train(self, historical_logs):
        """Train the anomaly detection model"""
        features = self.extract_features(historical_logs)
        self.model.fit(features)
        self.is_trained = True

    def detect_anomalies(self, new_logs):
        """Detect anomalies in new log entries"""
        if not self.is_trained:
            raise Exception("Model not trained")

        features = self.extract_features(new_logs)
        predictions = self.model.predict(features)

        anomalies = []
        for i, prediction in enumerate(predictions):
            if prediction == -1:  # -1 indicates anomaly
                anomalies.append({
                    'log_entry': new_logs[i],
                    'anomaly_score': self.model.score_samples([features[i]])[0]
                })

        return anomalies
```

