from elasticsearch import Elasticsearch
from datetime import datetime, timedelta

class SQLLogAnalyzer:
    def __init__(self):
        self.es = Elasticsearch(['elasticsearch:9200'])

    def detect_suspicious_patterns(self, timeframe_minutes=60):
        """Detect suspicious SQL patterns in recent logs"""
        query = {
            "query": {
                "bool": {
                    "must": [
                        {"range": {
                            "timestamp": {
                                "gte": f"now-{timeframe_minutes}m"
                            }
                        }},
                        {"term": {"validation_result": "rejected"}}
                    ]
                }
            },
            "aggs": {
                "by_user": {
                    "terms": {"field": "user_id", "size": 20},
                    "aggs": {
                        "by_pattern": {
                            "terms": {"field": "raw_input.keyword", "size": 5}
                        }
                    }
                },
                "by_ip": {
                    "terms": {"field": "ip_address", "size": 20}
                }
            }
        }

        results = self.es.search(index="sql-audit-*", body=query)
        return self._analyze_results(results)

    def detect_brute_force(self, threshold=10, window_minutes=5):
        """Detect potential brute force attacks"""
        query = {
            "query": {
                "range": {
                    "timestamp": {
                        "gte": f"now-{window_minutes}m"
                    }
                }
            },
            "aggs": {
                "failed_attempts": {
                    "filter": {"term": {"validation_result": "rejected"}},
                    "aggs": {
                        "by_user": {
                            "terms": {"field": "user_id", "size": 50},
                            "aggs": {
                                "attempt_count": {
                                    "value_count": {"field": "user_id"}
                                }
                            }
                        }
                    }
                }
            }
        }

        results = self.es.search(index="sql-audit-*", body=query)
        suspicious_users = []

        for bucket in results['aggregations']['failed_attempts']['by_user']['buckets']:
            if bucket['doc_count'] >= threshold:
                suspicious_users.append({
                    'user_id': bucket['key'],
                    'attempts': bucket['doc_count']
                })

        return suspicious_users

    def detect_data_exfiltration(self):
        """Detect potential data exfiltration patterns"""
        query = {
            "query": {
                "bool": {
                    "must": [
                        {"terms": {"query_type": ["SELECT"]}},
                        {"range": {
                            "timestamp": {
                                "gte": "now-1h"
                            }
                        }}
                    ]
                }
            },
            "aggs": {
                "large_result_sets": {
                    "filter": {"range": {"row_count": {"gte": 1000}}},
                    "aggs": {
                        "by_user": {
                            "terms": {"field": "user_id", "size": 20}
                        }
                    }
                }
            }
        }

        results = self.es.search(index="sql-audit-*", body=query)
        return results['aggregations']['large_result_sets']
